mapper.select:
select id, domain_type, domain_id, owner_member_id, actor_type, actor_member_id, actor_role_code,
       action, target_type, target_id, relation_id, before_json, after_json,
       reason, request_id, create_time
from business_audit_event
where domain_type = #{domainType}
  and domain_id = #{domainId}
  and action = #{action}
  and request_id = #{requestId}
for update

select count(1) from business_audit_event
where actor_member_id = #{actorMemberId}
  and action = #{action}
  and create_time >= curdate()
for update

select id, domain_type, domain_id, owner_member_id, actor_type, actor_member_id, actor_role_code,
       action, target_type, target_id, relation_id, before_json, after_json,
       reason, request_id, create_time
from business_audit_event

    and domain_type = #{domainType}
    and domain_id = #{domainId}
    and actor_member_id = #{actorId}
    and actor_type = #{actorType}
    and action = #{action}
    and target_type = #{targetType}
    and target_id = #{targetId}
    and create_time >= #{fromTime}
    and create_time <= #{toTime}
    and id < #{cursor}

order by id desc
limit #{fetchLimit}
